// src/lib/draft.js
//
// Rebuilding the Log page's editor from a saved draft.
//
// Kept free of imports on purpose so it can be loaded directly by a plain node test — the
// restore path is where workout data disappears silently, and a bug here shows an empty
// page rather than an error. Ids are generated by the caller (generateId lives in utils);
// passing one in keeps this module dependency-free.

/** An empty set row. `newId` must return a unique id. */
export function emptySet(n, newId) {
  return { id: newId(), set_number: n, weight: '', reps: '', note: '' }
}

/** An empty card for one library exercise. */
export function emptyLog(exercise, order, newId) {
  return {
    id: newId(),
    exercise_id: exercise.id,
    order,
    set_entries: [emptySet(1, newId)],
    _name: exercise.name,
    _image_url: exercise.image_url || null,
  }
}

/** A blank editor: one empty card per library exercise, which is what a new session shows. */
export function blankEditor(exercises, newId) {
  return (exercises || []).map((ex, i) => emptyLog(ex, i, newId))
}

/**
 * Rebuild the editor from a saved draft.
 *
 * Only exercises with a logged set are stored in the cloud draft. An empty card is not
 * workout data, and persisting one row per library exercise would fill exercise_logs with
 * logs that have no sets under them — including on the real save path, where Save prunes
 * them again anyway. So the draft carries only what was filled, and the rest of the editor
 * is re-seeded from the library here: every exercise visible again, with the saved ones
 * holding their sets.
 *
 * The trade-off is that an exercise deliberately removed from the editor returns as an
 * empty card. That is rare, harmless (an empty card is pruned on Save), and much cheaper
 * than a row per library exercise on every autosave.
 *
 * @param exercises the account's library, freshly read
 * @param savedLogs  the draft's logs, each carrying set_entries
 * @param newId      id generator, normally generateId
 */
export function mergeWithLibrary(exercises, savedLogs, newId) {
  const library = exercises || []
  const saved = savedLogs || []
  const byExercise = new Map(saved.map(log => [log.exercise_id, log]))

  const merged = library.map((exercise, i) => {
    const found = byExercise.get(exercise.id)
    if (!found) return emptyLog(exercise, i, newId)
    // order is re-derived from position rather than carried over: the saved order came
    // from a filtered list, so it no longer matches where the card now sits.
    return { ...found, order: i, _name: exercise.name, _image_url: exercise.image_url || null }
  })

  // A saved log whose exercise is missing from the library still belongs on screen. The
  // library read falls back to a default list when the network is unavailable, and quietly
  // dropping workout data is the exact failure this feature exists to prevent.
  const known = new Set(library.map(e => e.id))
  for (const log of saved) {
    if (known.has(log.exercise_id)) continue
    merged.push({
      ...log,
      order: merged.length,
      _name: log._name || 'Unknown',
      _image_url: log._image_url || null,
    })
  }

  return merged
}
